    "<p><strong>벡터곱(외적)</strong> $\\vec{u}\\times\\vec{v}=(u_2v_3-u_3v_2;\\ u_3v_1-u_1v_3;\\ u_1v_2-u_2v_1)$은 두 벡터에 모두 수직이고, 그 크기는 두 벡터로 만든 평행사변형의 넓이이다.\n       따라서 점 $P$와 직선 $X=Q+t\\vec{u}$ 사이의 거리는 $\\dfrac{|\\vec{QP}\\times\\vec{u}|}{|\\vec{u}|}$이고, 평면 $QRS$의 법선벡터는 $\\vec{QR}\\times\\vec{QS}$이다.</p>"
