   "summary": "대표적인 문제에서의 순열, 전순열과 조합(중복을 허락하지 않는 경우와 허락하는 경우).",
   "theory": [
    "<p><strong>곱의 법칙:</strong> 첫 번째 것을 $m$가지 방법으로 고르고, 그 각각에 대해 두 번째 것을 $n$가지 방법으로 고를 수 있으면 쌍의 개수는 $m\\cdot n$이다.\n       경우들이 서로 동시에 일어날 수 없을 때는 <strong>합의 법칙</strong>을 쓴다. 더 어려운 문제에서는 경우를 나누고(예: 일의 자리 숫자에 따라) 그 수를 더한다.</p>",
    "<table class=\"tbl\"><tr><th></th><th>중복을 허락하지 않음</th><th>중복을 허락함</th></tr>\n       <tr><td>$n$개에서 $k$개를 택하는 순열(순서가 중요함)</td><td>$V_k(n)=\\frac{n!}{(n-k)!}$</td><td>$V'_k(n)=n^k$</td></tr>\n       <tr><td>전순열(모두 나열)</td><td>$P(n)=n!$</td><td>$P'(k_1,\\dots,k_m)=\\frac{n!}{k_1!\\cdots k_m!}$</td></tr>\n       <tr><td>$n$개에서 $k$개를 택하는 조합(순서가 중요하지 않음)</td><td>$C_k(n)=\\binom{n}{k}=\\frac{n!}{k!(n-k)!}$</td><td>$C'_k(n)=\\binom{n+k-1}{k}$</td></tr></table>",
    "<p><strong>판단 방법:</strong> 순서가 중요한가(비밀번호, 역할 나누기, 수)? 그렇다면 순열이고, 그렇지 않다면(모둠 뽑기, 공을 한꺼번에 꺼내기) 조합이다.\n       여러 자리 수에서는 맨 앞자리에 0이 올 수 없다. 유용한 식: $\\binom{n}{k}=\\binom{n}{n-k}$, $\\binom{n}{2}=\\frac{n(n-1)}{2}$(예: $n$명이 서로 한 번씩 악수하는 횟수).</p>"
   ],
   "examples": [
    {
     "task": "숫자 $0, 1, 2, 3, 4$로 각 자리 숫자가 모두 다른 세 자리 수를 몇 개 만들 수 있는가?",
     "steps": [
      "맨 앞자리에는 0이 올 수 없다: $4$가지.",
      "둘째 자리에는 남은 $4$개 숫자(0 포함), 셋째 자리에는 $3$개.",
      "<strong>$4\\cdot 4\\cdot 3=48$개</strong>"
     ]
    },
    {
     "task": "남학생 8명과 여학생 6명 중에서 남학생 2명과 여학생 2명으로 이루어진 4명의 위원회를 뽑는다. 경우의 수는?",
     "steps": [
      "남학생은 $\\binom{8}{2}=28$가지, 여학생은 $\\binom{6}{2}=15$가지 방법으로 뽑는다.",
      "두 선택은 독립적이므로 곱의 법칙을 쓴다.",
      "<strong>$28\\cdot 15=420$가지</strong>"
     ]
    }
   ]
