    "<p><strong>연립방정식:</strong> 대입법과 가감법, 미지수가 세 개이면 차례로 소거한다. 두 일차방정식의 연립은 해가 하나이거나, 없거나,\n         무수히 많다(만나는 직선, 평행한 직선, 일치하는 직선). 비선형 연립방정식에서는 일차방정식에서 미지수 하나를 나타내어 대입한다.</p>",
    "<p><strong>자주 하는 실수:</strong> 조건을 잊는 것, 미지수가 있는 식으로 나누는 것(음수이거나 0일 수 있다), 결과를 잘못 합치는 것 — 연립부등식에서는 <strong>교집합</strong>을, “또는”일 때는 합집합을 구한다.</p>"
