    "<p><strong>그래프의 평행이동:</strong> $f(x-a)$는 그래프를 오른쪽으로 $a$만큼, $f(x)+b$는 위로 $b$만큼 평행이동하고, $-f(x)$는 $x$축에 대한 대칭이동이며, $|f(x)|$는 음수 부분을 위로 접어 올린다.</p>"
