  "$2\\sin x\\cos x {@0}=0 \\Rightarrow \\sin x\\,(2\\cos x {@1})=0$. $\\sin x=0$ pre $x\\in\\{0^\\circ; 180^\\circ\\}$, $\\cos x={@2}\\frac{{@3}}{2}$ pre $x\\in\\{{@4}\\}$. $K=\\{{@5}\\}$.": "$2\\sin x\\cos x {@0}=0 \\Rightarrow \\sin x\\,(2\\cos x {@1})=0$. $x\\in\\{0^\\circ; 180^\\circ\\}$일 때 $\\sin x=0$, $x\\in\\{{@4}\\}$일 때 $\\cos x={@2}\\frac{{@3}}{2}$. $K=\\{{@5}\\}$.",
