  "$D={@0}-4c=0 \\Rightarrow c={@1}$. Rovnica je potom $({@2})^2=0$ s dvojnásobným koreňom ${@3}$.": "$D={@0}-4c=0 \\Rightarrow c={@1}$. 그러면 방정식은 $({@2})^2=0$이고 중근은 ${@3}$이에요.",
  "$D={@0}-4p$. Podmienka {@1} dáva {@2}.": "$D={@0}-4p$. 조건 {@1}에서 {@2}를 얻어요.",
