  "Graf funkcie sin x / x s dierou v bode 0": "점 0에 구멍이 있는 함수 sin x / x의 그래프",
  "Graf funkcie x na tretiu mínus 3x s extrémami": "극값이 표시된 함수 x³ − 3x의 그래프",
