  "znížil": "내려갔어요",
  "zvýšil": "올라갔어요",
  "{@0} Bod $K$ je stred hrany ${@1}$. Vypočítaj vzdialenosť bodov ${@2}$ a $K$ v cm. {@3}": "{@0} 점 $K$는 모서리 ${@1}$의 중점이에요. 두 점 ${@2}$와 $K$ 사이의 거리를 cm 단위로 구하세요. {@3}",
  "{@0} Funkcia je <strong>{@1}</strong>.": "{@0} 함수는 <strong>{@1}</strong>예요.",
  "{@0} Normálové vektory sú ${@1}$ a ${@2}$. {@3}": "{@0} 법선벡터는 ${@1}$과 ${@2}$예요. {@3}",
  "{@0} Normálový vektor roviny ${@1}$ je $\\vec{n}={@2}$ (kolmý na $\\vec{{@3}{@4}}$ aj $\\vec{{@5}{@6}}$), smerový vektor priamky $\\vec{u}={@7}$. $\\vec{u}\\cdot\\vec{n}={@8}$. {@9}": "{@0} 평면 ${@1}$의 법선벡터는 $\\vec{n}={@2}$($\\vec{{@3}{@4}}$와 $\\vec{{@5}{@6}}$에 모두 수직)이고, 직선의 방향벡터는 $\\vec{u}={@7}$예요. $\\vec{u}\\cdot\\vec{n}={@8}$. {@9}",
  "{@0} Potom ${@1}{@2}$ a $K{@3}$. $|{@4}K|=\\sqrt{{@5}}=\\sqrt{{@6}}{@7}\\,\\text{cm}$.": "{@0} 그러면 ${@1}{@2}$이고 $K{@3}$이에요. $|{@4}K|=\\sqrt{{@5}}=\\sqrt{{@6}}{@7}\\,\\text{cm}$.",
  "{@0} Rovina ${@1}$ má normálový vektor $\\vec{n}={@2}$ a rovnicu ${@3}=0$. Pre ${@4}{@5}$: $d=\\dfrac{{@6}}{\\sqrt{{@7}}}\\approx {@8}\\,\\text{cm}$.": "{@0} 평면 ${@1}$의 법선벡터는 $\\vec{n}={@2}$이고 방정식은 ${@3}=0$이에요. ${@4}{@5}$에 대해: $d=\\dfrac{{@6}}{\\sqrt{{@7}}}\\approx {@8}\\,\\text{cm}$.",
  "{@0} Smerový vektor priamky $\\vec{u}=\\vec{{@1}}={@2}$, vektor $\\vec{{@3}{@4}}={@5}$. $d=\\dfrac{|\\vec{{@6}{@7}}\\times\\vec{u}|}{|\\vec{u}|}=\\dfrac{|{@8}|}{\\sqrt{{@9}}}\\approx {@10}\\,\\text{cm}$.": "{@0} 직선의 방향벡터 $\\vec{u}=\\vec{{@1}}={@2}$, 벡터 $\\vec{{@3}{@4}}={@5}$. $d=\\dfrac{|\\vec{{@6}{@7}}\\times\\vec{u}|}{|\\vec{u}|}=\\dfrac{|{@8}|}{\\sqrt{{@9}}}\\approx {@10}\\,\\text{cm}$.",
  "{@0} Správne je ${@1}$, $k\\in\\mathbb{Z}$.": "{@0} 올바른 답은 ${@1}$, $k\\in\\mathbb{Z}$예요.",
  "{@0} Substitúcia $t={@1} x$: ${@2}=0$, korene $t_1={@3}$, $t_2={@4}$. {@5} {@6}. Spolu $K=\\{{@7}\\}$.": "{@0} $t={@1} x$로 치환하면: ${@2}=0$, 근은 $t_1={@3}$, $t_2={@4}$. {@5} {@6}. 모두 합하면 $K=\\{{@7}\\}$.",
  "{@0} Vypočítaj $P(X={@1})$. {@2}": "{@0} $P(X={@1})$을 구하세요. {@2}",
  "{@0} Vypočítaj $P(X\\ge 1)$. {@1}": "{@0} $P(X\\ge 1)$을 구하세요. {@1}",
  "{@0} Vypočítaj pravdepodobnosť, že $X\\le 1$. {@1}": "{@0} $X\\le 1$일 확률을 구하세요. {@1}",
  "{@0} Vypočítaj strednú hodnotu $E(X)$ a rozptyl $D(X)$. Zadaj ich v tomto poradí oddelené bodkočiarkou (ako zlomky alebo desatinné čísla zaokrúhlené aspoň na 2 miesta).": "{@0} 기댓값 $E(X)$와 분산 $D(X)$를 구하세요. 이 순서로 세미콜론으로 구분해 입력하세요(분수 또는 적어도 소수 둘째 자리까지 반올림한 소수).",
  "{@0} Vypočítaj vzdialenosť vrcholu ${@1}$ od priamky ${@2}$ v cm. {@3}": "{@0} 꼭짓점 ${@1}$과 직선 ${@2}$ 사이의 거리를 cm 단위로 구하세요. {@3}",
  "{@0} Vypočítaj vzdialenosť vrcholu ${@1}$ od roviny ${@2}$ v cm. {@3}": "{@0} 꼭짓점 ${@1}$과 평면 ${@2}$ 사이의 거리를 cm 단위로 구하세요. {@3}",
  "{@0} Výsledok zaokrúhli na desatiny.": "{@0} 결과를 소수 첫째 자리까지 반올림하세요.",
  "{@0} Znak je <strong>{@1}</strong>.": "{@0} 이 변량은 <strong>{@1}</strong>이에요.",
  "{@0} chlapci": "남학생 {@0}명",
  "{@0} dievčatá": "여학생 {@0}명",
  "{@0} usporiadaného súboru. Aký je medián?": "{@0}(정렬한 자료 기준)이에요. 중앙값은 얼마일까요?",
  "{@0} zobrazuje známky z písomky v triede:{@1}Aký je medián známok?": "{@0}에 학급의 시험 점수가 나타나 있어요:{@1}점수의 중앙값은 무엇일까요?",
  "{@0} zobrazuje známky z písomky v triede:{@1}Vypočítaj priemernú známku. {@2}": "{@0}에 학급의 시험 점수가 나타나 있어요:{@1}평균 점수를 구하세요. {@2}",
  "{@0} {@1}": "{@0} {@1}",
  "{@0}Zaveď $t={@1} x$, vyrieš kvadratickú rovnicu a ponechaj len korene z intervalu $\\langle -1; 1\\rangle$.": "{@0}$t={@1} x$로 치환해서 이차방정식을 풀고, 구간 $\\langle -1; 1\\rangle$에 있는 근만 남기세요.",
  "Údaje najprv usporiadaj podľa veľkosti. Pri párnom počte je medián priemerom dvoch prostredných hodnôt.": "먼저 자료를 크기순으로 정렬하세요. 개수가 짝수이면 중앙값은 가운데 두 값의 평균이에요.",
  "Útvar ohraničený parabolou a priamkou": "포물선과 직선으로 둘러싸인 도형",
  "Čitateľ ${@0}$ rozlož na súčin ${@1}\\cdot(x+c)$. Aké je číslo $c$?": "분자 ${@0}$을 ${@1}\\cdot(x+c)$로 인수분해하세요. 수 $c$는 얼마일까요?",
  "Čitateľ derivácie ${@0}({@1})-({@2})\\cdot {@3}$ je po úprave konštanta. Aká?": "도함수의 분자 ${@0}({@1})-({@2})\\cdot {@3}$은 정리하면 상수예요. 얼마일까요?",
  "Čitateľ je nenulová konštanta a menovateľ sa blíži k nule, takže zlomok v absolútnej hodnote rastie nad všetky medze.": "분자는 0이 아닌 상수이고 분모는 0에 가까워지므로 분수의 절댓값은 한없이 커져요.",
  "Čitateľ má nižší stupeň než menovateľ, v čitateli preto zostane len nula a limita je $0$.": "분자의 차수가 분모보다 낮으므로 분자에는 0만 남고 극한은 $0$이에요.",
  "Čitateľ zmení znamienko, menovateľ nie: $f(-x)=-f(x)$.": "분자는 부호가 바뀌고 분모는 바뀌지 않아요: $f(-x)=-f(x)$.",
  "Čitateľa aj menovateľa vydelíme najvyššou mocninou menovateľa, teda ${@0}$. Všetky členy tvaru $\\frac{c}{x^k}$ sa blížia k nule. {@1}": "분자와 분모를 분모의 최고차 거듭제곱, 즉 ${@0}$으로 나눠요. $\\frac{c}{x^k}$ 꼴의 항은 모두 0에 가까워져요. {@1}",
  "Člen $uv'$ je $({@0})\\cdot\\frac{1}{x}$. Koľko je teda $f'(1)$?": "항 $uv'$는 $({@0})\\cdot\\frac{1}{x}$이에요. 그러면 $f'(1)$은 얼마일까요?",
  "Číslo $f({@0})$ nie je absolútny člen $q$. Dosaď do $y=f(x_0)+f'(x_0)(x-x_0)$ a roznásob zátvorku.": "수 $f({@0})$은 상수항 $q$가 아니에요. $y=f(x_0)+f'(x_0)(x-x_0)$에 대입하고 괄호를 전개하세요.",
  "Číslo z vodorovnej asymptoty $y=\\dots$ (limita pre $x\\to\\infty$)?": "수평점근선 $y=\\dots$의 수($x\\to\\infty$일 때의 극한)는 얼마일까요?",
  "Číslo zo zvislej asymptoty $x=\\dots$ (nulový bod menovateľa)?": "수직점근선 $x=\\dots$의 수(분모가 0이 되는 점)는 얼마일까요?",
  "čas behu na 100 m": "100 m 달리기 기록",
  "čierne": "개의 검은 공",
  "čiernych": "개의 검은 공",
  "ľubovoľnú cifru": "아무 숫자",
  "ľubovoľnú cifru okrem nuly": "0을 제외한 아무 숫자",
  "Žiaci odpovedali, ako chodia do školy:{@0}{@1} Výsledok zaokrúhli na desatiny.": "학생들이 학교에 어떻게 오는지 답했어요:{@0}{@1} 결과를 소수 첫째 자리까지 반올림하세요.",
  "Žiadny z nich neleží vo vnútri intervalu.": "그중 구간 안에 있는 것은 없어요.",
  "Žiak v teste s {@0} otázkami náhodne tipuje; každá otázka má štyri možnosti a práve jedna je správna. Náhodná premenná $X$ je počet správnych odpovedí.": "학생이 문제 {@0}개짜리 시험에서 무작위로 답을 찍어요. 각 문제에는 보기가 네 개 있고 정답은 정확히 하나예요. 확률변수 $X$는 맞힌 답의 개수예요.",
  "žiadny reálny koreň": "실근을 갖지 않음",
  "„Najviac jeden“ zahŕňa aj možnosť, že nenastane žiadny úspech. Pripočítaj $P(X=0)$.": "\"많아야 한 번\"에는 한 번도 성공하지 않는 경우도 포함돼요. $P(X=0)$을 더하세요.",
